update public.products set faqs_i18n='{"it":[{"q":"Come si presenta ANADROMED 50?","a":"ANADROMED 50 è uno steroide androgeno-anabolizzante orale (Steroide androgeno-anabolizzante) e contiene Oxymetholone 50mg/tab. Si presenta in forma di Compresse (uso orale) con concentrazione o dosaggio unitario 50 mg/tab, in confezione da 50 compresse — uso orale. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare è una proprietà chimica della molecola: tra gli orali, ad esempio, la methandienone aromatizza, mentre oxandrolone e stanozolol non aromatizzano. Il principio attivo specifico è indicato in Oxymetholone 50mg/tab."},{"q":"Cosa significa che è 17-alfa-alchilato?","a":"Molti steroidi orali sono 17-alfa-alchilati, una modifica chimica che ne consente il passaggio per via orale resistendo al metabolismo epatico di primo passaggio. È una caratteristica strutturale della molecola, non un consiglio d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"How is ANADROMED 50 presented?","a":"ANADROMED 50 is an oral androgenic-anabolic steroid (Steroide androgeno-anabolizzante) and contains Oxymetholone 50mg/tab. It comes in the form of Compresse (uso orale) with a concentration or unit dosage of 50 mg/tab, in a pack of 50 compresse — uso orale. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"Does it aromatize?","a":"The tendency to aromatize is a chemical property of the molecule: among orals, for example, methandienone aromatizes, whereas oxandrolone and stanozolol do not aromatize. The specific active ingredient is indicated in Oxymetholone 50mg/tab."},{"q":"What does 17-alpha-alkylated mean?","a":"Many oral steroids are 17-alpha-alkylated, a chemical modification that allows them to pass through the oral route by resisting first-pass hepatic metabolism. It is a structural characteristic of the molecule, not advice on use."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Wie wird ANADROMED 50 dargeboten?","a":"ANADROMED 50 ist ein orales androgen-anaboles Steroid (Steroide androgeno-anabolizzante) und enthält Oxymetholone 50mg/tab. Es liegt in Form von Compresse (uso orale) mit einer Konzentration oder Einzeldosierung von 50 mg/tab vor, in einer Packung zu 50 compresse — uso orale. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Aromatisiert es?","a":"Die Neigung zur Aromatisierung ist eine chemische Eigenschaft des Moleküls: Unter den oralen Präparaten aromatisiert beispielsweise Methandienon, während Oxandrolon und Stanozolol nicht aromatisieren. Der spezifische Wirkstoff ist in Oxymetholone 50mg/tab angegeben."},{"q":"Was bedeutet 17-alpha-alkyliert?","a":"Viele orale Steroide sind 17-alpha-alkyliert, eine chemische Modifikation, die die orale Aufnahme ermöglicht, indem sie dem hepatischen First-Pass-Metabolismus widersteht. Es ist ein strukturelles Merkmal des Moleküls, kein Anwendungshinweis."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, gemäß den Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Comment se présente ANADROMED 50 ?","a":"ANADROMED 50 est un stéroïde androgénique-anabolisant oral (Steroide androgeno-anabolizzante) et contient Oxymetholone 50mg/tab. Il se présente sous forme de Compresse (uso orale) avec une concentration ou un dosage unitaire de 50 mg/tab, en conditionnement de 50 compresse — uso orale. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Aromatise-t-il ?","a":"La tendance à aromatiser est une propriété chimique de la molécule : parmi les oraux, par exemple, la méthandiénone aromatise, tandis que l''oxandrolone et le stanozolol n''aromatisent pas. Le principe actif spécifique est indiqué dans Oxymetholone 50mg/tab."},{"q":"Que signifie 17-alpha-alkylé ?","a":"De nombreux stéroïdes oraux sont 17-alpha-alkylés, une modification chimique qui permet leur passage par voie orale en résistant au métabolisme hépatique de premier passage. Il s''agit d''une caractéristique structurelle de la molécule, non d''un conseil d''utilisation."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"Como se apresenta ANADROMED 50?","a":"ANADROMED 50 é um esteroide androgénico-anabolizante oral (Steroide androgeno-anabolizzante) e contém Oxymetholone 50mg/tab. Apresenta-se sob a forma de Compresse (uso orale) com uma concentração ou dosagem unitária de 50 mg/tab, em embalagem de 50 compresse — uso orale. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Aromatiza?","a":"A tendência para aromatizar é uma propriedade química da molécula: entre os orais, por exemplo, a metandienona aromatiza, enquanto a oxandrolona e o stanozolol não aromatizam. O princípio ativo específico está indicado em Oxymetholone 50mg/tab."},{"q":"O que significa ser 17-alfa-alquilado?","a":"Muitos esteroides orais são 17-alfa-alquilados, uma modificação química que permite a sua passagem por via oral, resistindo ao metabolismo hepático de primeira passagem. É uma característica estrutural da molécula, não um conselho de utilização."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='anadromed-50';
