update public.products set faqs_i18n='{"it":[{"q":"A cosa serve un inibitore dell''aromatasi?","a":"ARIMIMED 1 appartiene alla classe degli inibitori dell''aromatasi (Inibitore dell''aromatasi). A livello farmacologico questa classe agisce sull''enzima aromatasi, che converte gli androgeni in estrogeni. Il prodotto contiene Anastrozole 1mg/tab ed è fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Come si presenta il prodotto?","a":"Si presenta in forma di Compresse (uso orale) con concentrazione 1 mg/tab. La confezione standard è 50 compresse — uso orale."},{"q":"Che differenza c''è tra i vari inibitori dell''aromatasi?","a":"Anastrozolo, letrozolo ed exemestane sono tutti inibitori dell''aromatasi ma con struttura chimica differente: i primi due sono di tipo non steroideo e reversibile, l''exemestane è steroideo e irreversibile. Il principio attivo specifico di questo prodotto è indicato in Anastrozole 1mg/tab."},{"q":"Come si conserva?","a":"La conservazione consigliata è in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità. Fare sempre riferimento alle indicazioni riportate sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is an aromatase inhibitor used for?","a":"ARIMIMED 1 belongs to the class of aromatase inhibitors (Inibitore dell''aromatasi). Pharmacologically, this class acts on the aromatase enzyme, which converts androgens into estrogens. The product contains Anastrozole 1mg/tab and is supplied exclusively for research and analytical evaluation purposes only."},{"q":"How is the product presented?","a":"It comes in the form of Compresse (uso orale) with a concentration of 1 mg/tab. The standard packaging is 50 compresse — uso orale."},{"q":"What is the difference between the various aromatase inhibitors?","a":"Anastrozole, letrozole and exemestane are all aromatase inhibitors but with different chemical structures: the first two are non-steroidal and reversible, while exemestane is steroidal and irreversible. The specific active ingredient of this product is indicated in Anastrozole 1mg/tab."},{"q":"How is it stored?","a":"The recommended storage is in a cool, dry place, protected from direct light and humidity. Always refer to the instructions printed on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Wofür wird ein Aromatasehemmer verwendet?","a":"ARIMIMED 1 gehört zur Klasse der Aromatasehemmer (Inibitore dell''aromatasi). Pharmakologisch wirkt diese Klasse auf das Enzym Aromatase, das Androgene in Östrogene umwandelt. Das Produkt enthält Anastrozole 1mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Wie wird das Produkt dargeboten?","a":"Es liegt in Form von Compresse (uso orale) mit einer Konzentration von 1 mg/tab vor. Die Standardverpackung ist 50 compresse — uso orale."},{"q":"Worin unterscheiden sich die verschiedenen Aromatasehemmer?","a":"Anastrozol, Letrozol und Exemestan sind allesamt Aromatasehemmer, jedoch mit unterschiedlicher chemischer Struktur: Die ersten beiden sind nichtsteroidal und reversibel, Exemestan ist steroidal und irreversibel. Der spezifische Wirkstoff dieses Produkts ist in Anastrozole 1mg/tab angegeben."},{"q":"Wie wird es gelagert?","a":"Die empfohlene Lagerung erfolgt an einem kühlen, trockenen Ort, geschützt vor direktem Licht und Feuchtigkeit. Beachten Sie stets die Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"À quoi sert un inhibiteur de l''aromatase ?","a":"ARIMIMED 1 appartient à la classe des inhibiteurs de l''aromatase (Inibitore dell''aromatasi). Sur le plan pharmacologique, cette classe agit sur l''enzyme aromatase, qui convertit les androgènes en œstrogènes. Le produit contient Anastrozole 1mg/tab et est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme se présente le produit ?","a":"Il se présente sous forme de Compresse (uso orale) avec une concentration de 1 mg/tab. Le conditionnement standard est 50 compresse — uso orale."},{"q":"Quelle est la différence entre les divers inhibiteurs de l''aromatase ?","a":"L''anastrozole, le létrozole et l''exémestane sont tous des inhibiteurs de l''aromatase mais de structure chimique différente : les deux premiers sont de type non stéroïdien et réversible, l''exémestane est stéroïdien et irréversible. Le principe actif spécifique de ce produit est indiqué dans Anastrozole 1mg/tab."},{"q":"Comment se conserve-t-il ?","a":"La conservation recommandée est dans un endroit frais et sec, à l''abri de la lumière directe et de l''humidité. Se référer toujours aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"Para que serve um inibidor da aromatase?","a":"ARIMIMED 1 pertence à classe dos inibidores da aromatase (Inibitore dell''aromatasi). A nível farmacológico, esta classe atua sobre a enzima aromatase, que converte androgénios em estrogénios. O produto contém Anastrozole 1mg/tab e é fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Como se apresenta o produto?","a":"Apresenta-se sob a forma de Compresse (uso orale) com uma concentração de 1 mg/tab. A embalagem padrão é 50 compresse — uso orale."},{"q":"Qual é a diferença entre os vários inibidores da aromatase?","a":"Anastrozol, letrozol e exemestano são todos inibidores da aromatase, mas com estrutura química diferente: os dois primeiros são do tipo não esteroide e reversível, o exemestano é esteroide e irreversível. O princípio ativo específico deste produto está indicado em Anastrozole 1mg/tab."},{"q":"Como se conserva?","a":"A conservação recomendada é em local fresco e seco, ao abrigo da luz direta e da humidade. Consultar sempre as indicações apresentadas na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='arimimed-1';
