update public.products set faqs_i18n='{"it":[{"q":"Cosa contiene TELMIMED 40?","a":"TELMIMED 40 contiene Telmisartan 40mg/tab e appartiene alla classe Supporto / salute. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 40 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come utilizzarlo?","a":"Le informazioni disponibili riguardano composizione, classe farmacologica e caratteristiche del prodotto e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Come si conserva?","a":"Si consiglia di conservare il prodotto in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità, secondo le indicazioni riportate sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What does TELMIMED 40 contain?","a":"TELMIMED 40 contains Telmisartan 40mg/tab and belongs to the Supporto / salute class. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 40 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"Do you provide instructions on how to use it?","a":"The information available concerns composition, pharmacological class and product characteristics and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"How is it stored?","a":"It is recommended to store the product in a cool, dry place, protected from direct light and humidity, according to the instructions printed on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was enthält TELMIMED 40?","a":"TELMIMED 40 enthält Telmisartan 40mg/tab und gehört zur Klasse Supporto / salute. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 40 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Geben Sie Hinweise zur Anwendung?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, pharmakologische Klasse und Produkteigenschaften und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Wie wird es gelagert?","a":"Es wird empfohlen, das Produkt an einem kühlen, trockenen Ort, geschützt vor direktem Licht und Feuchtigkeit, gemäß den Angaben auf der Verpackung zu lagern."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Que contient TELMIMED 40 ?","a":"TELMIMED 40 contient Telmisartan 40mg/tab et appartient à la classe Supporto / salute. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 40 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Fournissez-vous des indications sur son utilisation ?","a":"Les informations disponibles concernent la composition, la classe pharmacologique et les caractéristiques du produit et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Comment se conserve-t-il ?","a":"Il est conseillé de conserver le produit dans un endroit frais et sec, à l''abri de la lumière directe et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que contém TELMIMED 40?","a":"TELMIMED 40 contém Telmisartan 40mg/tab e pertence à classe Supporto / salute. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 40 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Fornecem indicações sobre como utilizá-lo?","a":"As informações disponíveis dizem respeito à composição, classe farmacológica e características do produto e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"Como se conserva?","a":"Recomenda-se conservar o produto em local fresco e seco, ao abrigo da luz direta e da humidade, de acordo com as indicações apresentadas na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='telmimed-40';
update public.products set faqs_i18n='{"it":[{"q":"Cosa contiene questo prodotto tiroideo?","a":"THYROMED 50 contiene Levothyroxine Sodium (T4) 50mcg/tab e appartiene alla classe degli ormoni tiroidei (Ormone tiroideo), che comprende T3 (liotironina) e T4 (levotiroxina). È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Che differenza c''è tra T3 e T4?","a":"Il T4 è l''ormone tiroideo con emivita più lunga e viene convertito a livello periferico in T3, la forma metabolicamente più attiva. Il principio attivo specifico di questo prodotto è indicato in Levothyroxine Sodium (T4) 50mcg/tab."},{"q":"In che forma è disponibile?","a":"È disponibile come Compresse (uso orale) con concentrazione 50 mcg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Si consiglia la conservazione in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What does this thyroid product contain?","a":"THYROMED 50 contains Levothyroxine Sodium (T4) 50mcg/tab and belongs to the class of thyroid hormones (Ormone tiroideo), which includes T3 (liothyronine) and T4 (levothyroxine). It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"What is the difference between T3 and T4?","a":"T4 is the thyroid hormone with the longer half-life and is converted peripherally into T3, the metabolically more active form. The specific active ingredient of this product is indicated in Levothyroxine Sodium (T4) 50mcg/tab."},{"q":"In what form is it available?","a":"It is available as Compresse (uso orale) with a concentration of 50 mcg/tab, in a pack of 50 compresse — uso orale."},{"q":"How is it stored?","a":"Storage is recommended in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was enthält dieses Schilddrüsenprodukt?","a":"THYROMED 50 enthält Levothyroxine Sodium (T4) 50mcg/tab und gehört zur Klasse der Schilddrüsenhormone (Ormone tiroideo), die T3 (Liothyronin) und T4 (Levothyroxin) umfasst. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Worin unterscheiden sich T3 und T4?","a":"T4 ist das Schilddrüsenhormon mit der längeren Halbwertszeit und wird peripher in T3 umgewandelt, die metabolisch aktivere Form. Der spezifische Wirkstoff dieses Produkts ist in Levothyroxine Sodium (T4) 50mcg/tab angegeben."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist als Compresse (uso orale) mit einer Konzentration von 50 mcg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Wie wird es gelagert?","a":"Es wird eine Lagerung an einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit, gemäß den Angaben auf der Verpackung empfohlen."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Que contient ce produit thyroïdien ?","a":"THYROMED 50 contient Levothyroxine Sodium (T4) 50mcg/tab et appartient à la classe des hormones thyroïdiennes (Ormone tiroideo), qui comprend la T3 (liothyronine) et la T4 (lévothyroxine). Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Quelle est la différence entre la T3 et la T4 ?","a":"La T4 est l''hormone thyroïdienne à la demi-vie la plus longue et est convertie au niveau périphérique en T3, la forme métaboliquement la plus active. Le principe actif spécifique de ce produit est indiqué dans Levothyroxine Sodium (T4) 50mcg/tab."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 50 mcg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Comment se conserve-t-il ?","a":"Il est conseillé de le conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que contém este produto tiroideu?","a":"THYROMED 50 contém Levothyroxine Sodium (T4) 50mcg/tab e pertence à classe das hormonas tiroideias (Ormone tiroideo), que inclui a T3 (liotironina) e a T4 (levotiroxina). É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Qual é a diferença entre a T3 e a T4?","a":"A T4 é a hormona tiroideia com a semivida mais longa e é convertida a nível periférico em T3, a forma metabolicamente mais ativa. O princípio ativo específico deste produto está indicado em Levothyroxine Sodium (T4) 50mcg/tab."},{"q":"Em que forma está disponível?","a":"Está disponível como Compresse (uso orale) com uma concentração de 50 mcg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Como se conserva?","a":"Recomenda-se a conservação em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='thyromed-50';
update public.products set faqs_i18n='{"it":[{"q":"Come si presenta TURIMED 10?","a":"TURIMED 10 è uno steroide androgeno-anabolizzante orale (Steroide androgeno-anabolizzante) e contiene Chlorodehydromethyltestosterone 10mg/tab. Si presenta in forma di Compresse (uso orale) con concentrazione o dosaggio unitario 10 mg/tab, in confezione da 50 compresse — uso orale. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare è una proprietà chimica della molecola: tra gli orali, ad esempio, la methandienone aromatizza, mentre oxandrolone e stanozolol non aromatizzano. Il principio attivo specifico è indicato in Chlorodehydromethyltestosterone 10mg/tab."},{"q":"Cosa significa che è 17-alfa-alchilato?","a":"Molti steroidi orali sono 17-alfa-alchilati, una modifica chimica che ne consente il passaggio per via orale resistendo al metabolismo epatico di primo passaggio. È una caratteristica strutturale della molecola, non un consiglio d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"How is TURIMED 10 presented?","a":"TURIMED 10 is an oral androgenic-anabolic steroid (Steroide androgeno-anabolizzante) and contains Chlorodehydromethyltestosterone 10mg/tab. It comes in the form of Compresse (uso orale) with a concentration or unit dosage of 10 mg/tab, in a pack of 50 compresse — uso orale. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"Does it aromatize?","a":"The tendency to aromatize is a chemical property of the molecule: among orals, for example, methandienone aromatizes, whereas oxandrolone and stanozolol do not aromatize. The specific active ingredient is indicated in Chlorodehydromethyltestosterone 10mg/tab."},{"q":"What does 17-alpha-alkylated mean?","a":"Many oral steroids are 17-alpha-alkylated, a chemical modification that allows them to pass through the oral route by resisting first-pass hepatic metabolism. It is a structural characteristic of the molecule, not advice on use."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Wie wird TURIMED 10 dargeboten?","a":"TURIMED 10 ist ein orales androgen-anaboles Steroid (Steroide androgeno-anabolizzante) und enthält Chlorodehydromethyltestosterone 10mg/tab. Es liegt in Form von Compresse (uso orale) mit einer Konzentration oder Einzeldosierung von 10 mg/tab vor, in einer Packung zu 50 compresse — uso orale. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Aromatisiert es?","a":"Die Neigung zur Aromatisierung ist eine chemische Eigenschaft des Moleküls: Unter den oralen Präparaten aromatisiert beispielsweise Methandienon, während Oxandrolon und Stanozolol nicht aromatisieren. Der spezifische Wirkstoff ist in Chlorodehydromethyltestosterone 10mg/tab angegeben."},{"q":"Was bedeutet 17-alpha-alkyliert?","a":"Viele orale Steroide sind 17-alpha-alkyliert, eine chemische Modifikation, die die orale Aufnahme ermöglicht, indem sie dem hepatischen First-Pass-Metabolismus widersteht. Es ist ein strukturelles Merkmal des Moleküls, kein Anwendungshinweis."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, gemäß den Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Comment se présente TURIMED 10 ?","a":"TURIMED 10 est un stéroïde androgénique-anabolisant oral (Steroide androgeno-anabolizzante) et contient Chlorodehydromethyltestosterone 10mg/tab. Il se présente sous forme de Compresse (uso orale) avec une concentration ou un dosage unitaire de 10 mg/tab, en conditionnement de 50 compresse — uso orale. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Aromatise-t-il ?","a":"La tendance à aromatiser est une propriété chimique de la molécule : parmi les oraux, par exemple, la méthandiénone aromatise, tandis que l''oxandrolone et le stanozolol n''aromatisent pas. Le principe actif spécifique est indiqué dans Chlorodehydromethyltestosterone 10mg/tab."},{"q":"Que signifie 17-alpha-alkylé ?","a":"De nombreux stéroïdes oraux sont 17-alpha-alkylés, une modification chimique qui permet leur passage par voie orale en résistant au métabolisme hépatique de premier passage. Il s''agit d''une caractéristique structurelle de la molécule, non d''un conseil d''utilisation."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"Como se apresenta TURIMED 10?","a":"TURIMED 10 é um esteroide androgénico-anabolizante oral (Steroide androgeno-anabolizzante) e contém Chlorodehydromethyltestosterone 10mg/tab. Apresenta-se sob a forma de Compresse (uso orale) com uma concentração ou dosagem unitária de 10 mg/tab, em embalagem de 50 compresse — uso orale. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Aromatiza?","a":"A tendência para aromatizar é uma propriedade química da molécula: entre os orais, por exemplo, a metandienona aromatiza, enquanto a oxandrolona e o stanozolol não aromatizam. O princípio ativo específico está indicado em Chlorodehydromethyltestosterone 10mg/tab."},{"q":"O que significa ser 17-alfa-alquilado?","a":"Muitos esteroides orais são 17-alfa-alquilados, uma modificação química que permite a sua passagem por via oral, resistindo ao metabolismo hepático de primeira passagem. É uma característica estrutural da molécula, não um conselho de utilização."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='turimed-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un inibitore della PDE5?","a":"VIAMED 20 appartiene alla classe degli inibitori della fosfodiesterasi di tipo 5 (Inibitore PDE5), a cui appartengono tadalafil e sildenafil. Queste molecole inibiscono l''enzima PDE5. Il principio attivo è Sildenafil Citrate 20mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Che differenza c''è tra tadalafil e sildenafil?","a":"Entrambi inibiscono la PDE5, ma differiscono per struttura chimica ed emivita: il tadalafil ha un''emivita più lunga rispetto al sildenafil. Il principio attivo specifico è indicato in Sildenafil Citrate 20mg/tab."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 20 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, come indicato sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a PDE5 inhibitor?","a":"VIAMED 20 belongs to the class of phosphodiesterase type 5 inhibitors (Inibitore PDE5), to which tadalafil and sildenafil belong. These molecules inhibit the PDE5 enzyme. The active ingredient is Sildenafil Citrate 20mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"What is the difference between tadalafil and sildenafil?","a":"Both inhibit PDE5, but they differ in chemical structure and half-life: tadalafil has a longer half-life than sildenafil. The specific active ingredient is indicated in Sildenafil Citrate 20mg/tab."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 20 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, as indicated on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein PDE5-Hemmer?","a":"VIAMED 20 gehört zur Klasse der Phosphodiesterase-Typ-5-Hemmer (Inibitore PDE5), zu der Tadalafil und Sildenafil gehören. Diese Moleküle hemmen das Enzym PDE5. Der Wirkstoff ist Sildenafil Citrate 20mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Worin unterscheiden sich Tadalafil und Sildenafil?","a":"Beide hemmen PDE5, unterscheiden sich jedoch in der chemischen Struktur und der Halbwertszeit: Tadalafil hat eine längere Halbwertszeit als Sildenafil. Der spezifische Wirkstoff ist in Sildenafil Citrate 20mg/tab angegeben."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 20 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, wie auf der Verpackung angegeben."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un inhibiteur de la PDE5 ?","a":"VIAMED 20 appartient à la classe des inhibiteurs de la phosphodiestérase de type 5 (Inibitore PDE5), à laquelle appartiennent le tadalafil et le sildénafil. Ces molécules inhibent l''enzyme PDE5. Le principe actif est Sildenafil Citrate 20mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Quelle est la différence entre le tadalafil et le sildénafil ?","a":"Tous deux inhibent la PDE5, mais ils diffèrent par leur structure chimique et leur demi-vie : le tadalafil a une demi-vie plus longue que le sildénafil. Le principe actif spécifique est indiqué dans Sildenafil Citrate 20mg/tab."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 20 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, comme indiqué sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um inibidor da PDE5?","a":"VIAMED 20 pertence à classe dos inibidores da fosfodiesterase do tipo 5 (Inibitore PDE5), à qual pertencem o tadalafil e o sildenafil. Estas moléculas inibem a enzima PDE5. O princípio ativo é Sildenafil Citrate 20mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Qual é a diferença entre o tadalafil e o sildenafil?","a":"Ambos inibem a PDE5, mas diferem na estrutura química e na semivida: o tadalafil tem uma semivida mais longa do que o sildenafil. O princípio ativo específico está indicado em Sildenafil Citrate 20mg/tab."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 20 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, conforme indicado na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='viamed-20';
update public.products set faqs_i18n='{"it":[{"q":"Come si presenta WINIMED 10?","a":"WINIMED 10 è uno steroide androgeno-anabolizzante orale (Steroide androgeno-anabolizzante) e contiene Stanozolol 10mg/tab. Si presenta in forma di Compresse (uso orale) con concentrazione o dosaggio unitario 10 mg/tab, in confezione da 50 compresse — uso orale. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare è una proprietà chimica della molecola: tra gli orali, ad esempio, la methandienone aromatizza, mentre oxandrolone e stanozolol non aromatizzano. Il principio attivo specifico è indicato in Stanozolol 10mg/tab."},{"q":"Cosa significa che è 17-alfa-alchilato?","a":"Molti steroidi orali sono 17-alfa-alchilati, una modifica chimica che ne consente il passaggio per via orale resistendo al metabolismo epatico di primo passaggio. È una caratteristica strutturale della molecola, non un consiglio d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"How is WINIMED 10 presented?","a":"WINIMED 10 is an oral androgenic-anabolic steroid (Steroide androgeno-anabolizzante) and contains Stanozolol 10mg/tab. It comes in the form of Compresse (uso orale) with a concentration or unit dosage of 10 mg/tab, in a pack of 50 compresse — uso orale. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"Does it aromatize?","a":"The tendency to aromatize is a chemical property of the molecule: among orals, for example, methandienone aromatizes, whereas oxandrolone and stanozolol do not aromatize. The specific active ingredient is indicated in Stanozolol 10mg/tab."},{"q":"What does 17-alpha-alkylated mean?","a":"Many oral steroids are 17-alpha-alkylated, a chemical modification that allows them to pass through the oral route by resisting first-pass hepatic metabolism. It is a structural characteristic of the molecule, not advice on use."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Wie wird WINIMED 10 dargeboten?","a":"WINIMED 10 ist ein orales androgen-anaboles Steroid (Steroide androgeno-anabolizzante) und enthält Stanozolol 10mg/tab. Es liegt in Form von Compresse (uso orale) mit einer Konzentration oder Einzeldosierung von 10 mg/tab vor, in einer Packung zu 50 compresse — uso orale. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Aromatisiert es?","a":"Die Neigung zur Aromatisierung ist eine chemische Eigenschaft des Moleküls: Unter den oralen Präparaten aromatisiert beispielsweise Methandienon, während Oxandrolon und Stanozolol nicht aromatisieren. Der spezifische Wirkstoff ist in Stanozolol 10mg/tab angegeben."},{"q":"Was bedeutet 17-alpha-alkyliert?","a":"Viele orale Steroide sind 17-alpha-alkyliert, eine chemische Modifikation, die die orale Aufnahme ermöglicht, indem sie dem hepatischen First-Pass-Metabolismus widersteht. Es ist ein strukturelles Merkmal des Moleküls, kein Anwendungshinweis."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, gemäß den Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Comment se présente WINIMED 10 ?","a":"WINIMED 10 est un stéroïde androgénique-anabolisant oral (Steroide androgeno-anabolizzante) et contient Stanozolol 10mg/tab. Il se présente sous forme de Compresse (uso orale) avec une concentration ou un dosage unitaire de 10 mg/tab, en conditionnement de 50 compresse — uso orale. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Aromatise-t-il ?","a":"La tendance à aromatiser est une propriété chimique de la molécule : parmi les oraux, par exemple, la méthandiénone aromatise, tandis que l''oxandrolone et le stanozolol n''aromatisent pas. Le principe actif spécifique est indiqué dans Stanozolol 10mg/tab."},{"q":"Que signifie 17-alpha-alkylé ?","a":"De nombreux stéroïdes oraux sont 17-alpha-alkylés, une modification chimique qui permet leur passage par voie orale en résistant au métabolisme hépatique de premier passage. Il s''agit d''une caractéristique structurelle de la molécule, non d''un conseil d''utilisation."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"Como se apresenta WINIMED 10?","a":"WINIMED 10 é um esteroide androgénico-anabolizante oral (Steroide androgeno-anabolizzante) e contém Stanozolol 10mg/tab. Apresenta-se sob a forma de Compresse (uso orale) com uma concentração ou dosagem unitária de 10 mg/tab, em embalagem de 50 compresse — uso orale. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Aromatiza?","a":"A tendência para aromatizar é uma propriedade química da molécula: entre os orais, por exemplo, a metandienona aromatiza, enquanto a oxandrolona e o stanozolol não aromatizam. O princípio ativo específico está indicado em Stanozolol 10mg/tab."},{"q":"O que significa ser 17-alfa-alquilado?","a":"Muitos esteroides orais são 17-alfa-alquilados, uma modificação química que permite a sua passagem por via oral, resistindo ao metabolismo hepático de primeira passagem. É uma característica estrutural da molécula, não um conselho de utilização."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='winimed-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un agonista PPAR-delta?","a":"GW501516 10 appartiene alla classe degli agonisti del recettore PPARδ (Agonista PPARδ), a cui appartiene la cardarine (GW-501516). Queste molecole attivano il recettore nucleare PPARδ. Il principio attivo è Cardarine (GW-501516) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La cardarine è un SARM?","a":"No. Nonostante venga spesso associata ai SARM nella comunicazione commerciale, la cardarine è un agonista PPARδ e non interagisce con il recettore androgeno. Sono classi farmacologiche diverse."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità, come indicato sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a PPAR-delta agonist?","a":"GW501516 10 belongs to the class of PPARδ receptor agonists (Agonista PPARδ), to which cardarine (GW-501516) belongs. These molecules activate the nuclear receptor PPARδ. The active ingredient is Cardarine (GW-501516) 10mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is cardarine a SARM?","a":"No. Although it is often associated with SARMs in commercial communication, cardarine is a PPARδ agonist and does not interact with the androgen receptor. They are different pharmacological classes."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 10 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from direct light and humidity, as indicated on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein PPAR-delta-Agonist?","a":"GW501516 10 gehört zur Klasse der PPARδ-Rezeptoragonisten (Agonista PPARδ), zu der Cardarine (GW-501516) gehört. Diese Moleküle aktivieren den Kernrezeptor PPARδ. Der Wirkstoff ist Cardarine (GW-501516) 10mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Ist Cardarine ein SARM?","a":"Nein. Obwohl es in der kommerziellen Kommunikation oft mit SARMs in Verbindung gebracht wird, ist Cardarine ein PPARδ-Agonist und interagiert nicht mit dem Androgenrezeptor. Es sind unterschiedliche pharmakologische Klassen."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 10 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor direktem Licht und Feuchtigkeit lagern, wie auf der Verpackung angegeben."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un agoniste PPAR-delta ?","a":"GW501516 10 appartient à la classe des agonistes du récepteur PPARδ (Agonista PPARδ), à laquelle appartient la cardarine (GW-501516). Ces molécules activent le récepteur nucléaire PPARδ. Le principe actif est Cardarine (GW-501516) 10mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La cardarine est-elle un SARM ?","a":"Non. Bien qu''elle soit souvent associée aux SARM dans la communication commerciale, la cardarine est un agoniste PPARδ et n''interagit pas avec le récepteur androgène. Ce sont des classes pharmacologiques différentes."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 10 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière directe et de l''humidité, comme indiqué sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um agonista PPAR-delta?","a":"GW501516 10 pertence à classe dos agonistas do recetor PPARδ (Agonista PPARδ), à qual pertence a cardarina (GW-501516). Estas moléculas ativam o recetor nuclear PPARδ. O princípio ativo é Cardarine (GW-501516) 10mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"A cardarina é um SARM?","a":"Não. Embora seja frequentemente associada aos SARM na comunicação comercial, a cardarina é um agonista PPARδ e não interage com o recetor androgénico. São classes farmacológicas diferentes."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 10 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz direta e da humidade, conforme indicado na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='gw501516-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un SARM?","a":"LGD4033 10 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Ligandrol (LGD-4033) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a SARM?","a":"LGD4033 10 belongs to the class of selective androgen receptor modulators (SARM), to which ostarine, ligandrol and RAD-140 belong. These molecules interact selectively with the androgen receptor. The active ingredient is Ligandrol (LGD-4033) 10mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is a SARM a steroid?","a":"No. SARMs act on the same androgen receptor but have a non-steroidal structure and a different selectivity profile compared to androgenic-anabolic steroids. They are distinct classes."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 10 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"Do you provide instructions on how to take it?","a":"The information available concerns composition, class and mechanism and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein SARM?","a":"LGD4033 10 gehört zur Klasse der selektiven Androgenrezeptor-Modulatoren (SARM), zu der Ostarine, Ligandrol und RAD-140 gehören. Diese Moleküle interagieren selektiv mit dem Androgenrezeptor. Der Wirkstoff ist Ligandrol (LGD-4033) 10mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Ist ein SARM ein Steroid?","a":"Nein. SARMs wirken auf denselben Androgenrezeptor, haben jedoch eine nichtsteroidale Struktur und ein anderes Selektivitätsprofil als androgen-anabole Steroide. Es sind unterschiedliche Klassen."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 10 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Geben Sie Hinweise zur Einnahme?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, Klasse und Mechanismus und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un SARM ?","a":"LGD4033 10 appartient à la classe des modulateurs sélectifs du récepteur androgène (SARM), à laquelle appartiennent l''ostarine, le ligandrol et le RAD-140. Ces molécules interagissent de manière sélective avec le récepteur androgène. Le principe actif est Ligandrol (LGD-4033) 10mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Un SARM est-il un stéroïde ?","a":"Non. Les SARM agissent sur le même récepteur androgène mais présentent une structure non stéroïdienne et un profil de sélectivité différent de celui des stéroïdes androgéniques-anabolisants. Ce sont des classes distinctes."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 10 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Fournissez-vous des indications sur la façon de le prendre ?","a":"Les informations disponibles concernent la composition, la classe et le mécanisme et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um SARM?","a":"LGD4033 10 pertence à classe dos moduladores seletivos do recetor androgénico (SARM), à qual pertencem a ostarina, o ligandrol e o RAD-140. Estas moléculas interagem de forma seletiva com o recetor androgénico. O princípio ativo é Ligandrol (LGD-4033) 10mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Um SARM é um esteroide?","a":"Não. Os SARM atuam sobre o mesmo recetor androgénico, mas têm uma estrutura não esteroide e um perfil de seletividade diferente do dos esteroides androgénicos-anabolizantes. São classes distintas."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 10 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Fornecem indicações sobre como tomá-lo?","a":"As informações disponíveis dizem respeito à composição, classe e mecanismo e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='lgd4033-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un SARM?","a":"MK2866 10 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Ostarine (MK-2866) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a SARM?","a":"MK2866 10 belongs to the class of selective androgen receptor modulators (SARM), to which ostarine, ligandrol and RAD-140 belong. These molecules interact selectively with the androgen receptor. The active ingredient is Ostarine (MK-2866) 10mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is a SARM a steroid?","a":"No. SARMs act on the same androgen receptor but have a non-steroidal structure and a different selectivity profile compared to androgenic-anabolic steroids. They are distinct classes."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 10 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"Do you provide instructions on how to take it?","a":"The information available concerns composition, class and mechanism and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein SARM?","a":"MK2866 10 gehört zur Klasse der selektiven Androgenrezeptor-Modulatoren (SARM), zu der Ostarine, Ligandrol und RAD-140 gehören. Diese Moleküle interagieren selektiv mit dem Androgenrezeptor. Der Wirkstoff ist Ostarine (MK-2866) 10mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Ist ein SARM ein Steroid?","a":"Nein. SARMs wirken auf denselben Androgenrezeptor, haben jedoch eine nichtsteroidale Struktur und ein anderes Selektivitätsprofil als androgen-anabole Steroide. Es sind unterschiedliche Klassen."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 10 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Geben Sie Hinweise zur Einnahme?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, Klasse und Mechanismus und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un SARM ?","a":"MK2866 10 appartient à la classe des modulateurs sélectifs du récepteur androgène (SARM), à laquelle appartiennent l''ostarine, le ligandrol et le RAD-140. Ces molécules interagissent de manière sélective avec le récepteur androgène. Le principe actif est Ostarine (MK-2866) 10mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Un SARM est-il un stéroïde ?","a":"Non. Les SARM agissent sur le même récepteur androgène mais présentent une structure non stéroïdienne et un profil de sélectivité différent de celui des stéroïdes androgéniques-anabolisants. Ce sont des classes distinctes."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 10 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Fournissez-vous des indications sur la façon de le prendre ?","a":"Les informations disponibles concernent la composition, la classe et le mécanisme et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um SARM?","a":"MK2866 10 pertence à classe dos moduladores seletivos do recetor androgénico (SARM), à qual pertencem a ostarina, o ligandrol e o RAD-140. Estas moléculas interagem de forma seletiva com o recetor androgénico. O princípio ativo é Ostarine (MK-2866) 10mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Um SARM é um esteroide?","a":"Não. Os SARM atuam sobre o mesmo recetor androgénico, mas têm uma estrutura não esteroide e um perfil de seletividade diferente do dos esteroides androgénicos-anabolizantes. São classes distintas."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 10 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Fornecem indicações sobre como tomá-lo?","a":"As informações disponíveis dizem respeito à composição, classe e mecanismo e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='mk2866-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un secretagogo del GH?","a":"MK677 10 appartiene alla classe dei secretagoghi dell''ormone della crescita (Secretagogo GH), a cui appartiene l''ibutamoren (MK-677). Queste molecole stimolano il recettore della grelina favorendo la secrezione endogena di GH. Il principio attivo è Ibutamoren (MK-677) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un secretagogo è la stessa cosa dell''ormone della crescita?","a":"No. L''ormone della crescita è la somatropina somministrata direttamente, mentre un secretagogo come l''MK-677 agisce sul recettore della grelina stimolando la produzione endogena di GH. Sono due categorie distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a GH secretagogue?","a":"MK677 10 belongs to the class of growth hormone secretagogues (Secretagogo GH), to which ibutamoren (MK-677) belongs. These molecules stimulate the ghrelin receptor, promoting the endogenous secretion of GH. The active ingredient is Ibutamoren (MK-677) 10mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is a secretagogue the same thing as growth hormone?","a":"No. Growth hormone is somatropin administered directly, whereas a secretagogue such as MK-677 acts on the ghrelin receptor, stimulating the endogenous production of GH. These are two distinct categories."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 10 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein GH-Sekretagogum?","a":"MK677 10 gehört zur Klasse der Wachstumshormon-Sekretagoga (Secretagogo GH), zu der Ibutamoren (MK-677) gehört. Diese Moleküle stimulieren den Ghrelinrezeptor und fördern die endogene GH-Sekretion. Der Wirkstoff ist Ibutamoren (MK-677) 10mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Ist ein Sekretagogum dasselbe wie Wachstumshormon?","a":"Nein. Wachstumshormon ist direkt verabreichtes Somatropin, während ein Sekretagogum wie MK-677 auf den Ghrelinrezeptor wirkt und die endogene GH-Produktion stimuliert. Es handelt sich um zwei unterschiedliche Kategorien."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 10 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, gemäß den Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un sécrétagogue de la GH ?","a":"MK677 10 appartient à la classe des sécrétagogues de l''hormone de croissance (Secretagogo GH), à laquelle appartient l''ibutamorène (MK-677). Ces molécules stimulent le récepteur de la ghréline en favorisant la sécrétion endogène de GH. Le principe actif est Ibutamoren (MK-677) 10mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Un sécrétagogue est-il la même chose que l''hormone de croissance ?","a":"Non. L''hormone de croissance est la somatropine administrée directement, tandis qu''un sécrétagogue comme le MK-677 agit sur le récepteur de la ghréline en stimulant la production endogène de GH. Ce sont deux catégories distinctes."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 10 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um secretagogo da GH?","a":"MK677 10 pertence à classe dos secretagogos da hormona do crescimento (Secretagogo GH), à qual pertence o ibutamoren (MK-677). Estas moléculas estimulam o recetor da grelina, favorecendo a secreção endógena de GH. O princípio ativo é Ibutamoren (MK-677) 10mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Um secretagogo é a mesma coisa que a hormona do crescimento?","a":"Não. A hormona do crescimento é a somatropina administrada diretamente, enquanto um secretagogo como o MK-677 atua sobre o recetor da grelina, estimulando a produção endógena de GH. São duas categorias distintas."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 10 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='mk677-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un SARM?","a":"RAD140 10 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Testolone (RAD-140) 10mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 10 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a SARM?","a":"RAD140 10 belongs to the class of selective androgen receptor modulators (SARM), to which ostarine, ligandrol and RAD-140 belong. These molecules interact selectively with the androgen receptor. The active ingredient is Testolone (RAD-140) 10mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is a SARM a steroid?","a":"No. SARMs act on the same androgen receptor but have a non-steroidal structure and a different selectivity profile compared to androgenic-anabolic steroids. They are distinct classes."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 10 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"Do you provide instructions on how to take it?","a":"The information available concerns composition, class and mechanism and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein SARM?","a":"RAD140 10 gehört zur Klasse der selektiven Androgenrezeptor-Modulatoren (SARM), zu der Ostarine, Ligandrol und RAD-140 gehören. Diese Moleküle interagieren selektiv mit dem Androgenrezeptor. Der Wirkstoff ist Testolone (RAD-140) 10mg/tab und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Ist ein SARM ein Steroid?","a":"Nein. SARMs wirken auf denselben Androgenrezeptor, haben jedoch eine nichtsteroidale Struktur und ein anderes Selektivitätsprofil als androgen-anabole Steroide. Es sind unterschiedliche Klassen."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Compresse (uso orale) mit einer Konzentration von 10 mg/tab erhältlich, in einer Packung zu 50 compresse — uso orale."},{"q":"Geben Sie Hinweise zur Einnahme?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, Klasse und Mechanismus und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un SARM ?","a":"RAD140 10 appartient à la classe des modulateurs sélectifs du récepteur androgène (SARM), à laquelle appartiennent l''ostarine, le ligandrol et le RAD-140. Ces molécules interagissent de manière sélective avec le récepteur androgène. Le principe actif est Testolone (RAD-140) 10mg/tab, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Un SARM est-il un stéroïde ?","a":"Non. Les SARM agissent sur le même récepteur androgène mais présentent une structure non stéroïdienne et un profil de sélectivité différent de celui des stéroïdes androgéniques-anabolisants. Ce sont des classes distinctes."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Compresse (uso orale) avec une concentration de 10 mg/tab, en conditionnement de 50 compresse — uso orale."},{"q":"Fournissez-vous des indications sur la façon de le prendre ?","a":"Les informations disponibles concernent la composition, la classe et le mécanisme et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um SARM?","a":"RAD140 10 pertence à classe dos moduladores seletivos do recetor androgénico (SARM), à qual pertencem a ostarina, o ligandrol e o RAD-140. Estas moléculas interagem de forma seletiva com o recetor androgénico. O princípio ativo é Testolone (RAD-140) 10mg/tab, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Um SARM é um esteroide?","a":"Não. Os SARM atuam sobre o mesmo recetor androgénico, mas têm uma estrutura não esteroide e um perfil de seletividade diferente do dos esteroides androgénicos-anabolizantes. São classes distintas."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Compresse (uso orale) com uma concentração de 10 mg/tab, em embalagem de 50 compresse — uso orale."},{"q":"Fornecem indicações sobre como tomá-lo?","a":"As informações disponíveis dizem respeito à composição, classe e mecanismo e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='rad140-10';
update public.products set faqs_i18n='{"it":[{"q":"Come si presenta S23 10?","a":"S23 10 è uno steroide androgeno-anabolizzante orale (SARM) e contiene S23 10mg/tab. Si presenta in forma di Compresse (uso orale) con concentrazione o dosaggio unitario 10 mg/tab, in confezione da 50 compresse — uso orale. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Aromatizza?","a":"La tendenza ad aromatizzare è una proprietà chimica della molecola: tra gli orali, ad esempio, la methandienone aromatizza, mentre oxandrolone e stanozolol non aromatizzano. Il principio attivo specifico è indicato in S23 10mg/tab."},{"q":"Cosa significa che è 17-alfa-alchilato?","a":"Molti steroidi orali sono 17-alfa-alchilati, una modifica chimica che ne consente il passaggio per via orale resistendo al metabolismo epatico di primo passaggio. È una caratteristica strutturale della molecola, non un consiglio d''uso."},{"q":"Come si conserva?","a":"Conservare in luogo fresco e asciutto, al riparo dalla luce e dall''umidità, secondo le indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"How is S23 10 presented?","a":"S23 10 is an oral androgenic-anabolic steroid (SARM) and contains S23 10mg/tab. It comes in the form of Compresse (uso orale) with a concentration or unit dosage of 10 mg/tab, in a pack of 50 compresse — uso orale. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"Does it aromatize?","a":"The tendency to aromatize is a chemical property of the molecule: among orals, for example, methandienone aromatizes, whereas oxandrolone and stanozolol do not aromatize. The specific active ingredient is indicated in S23 10mg/tab."},{"q":"What does 17-alpha-alkylated mean?","a":"Many oral steroids are 17-alpha-alkylated, a chemical modification that allows them to pass through the oral route by resisting first-pass hepatic metabolism. It is a structural characteristic of the molecule, not advice on use."},{"q":"How is it stored?","a":"Store in a cool, dry place, protected from light and humidity, according to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Wie wird S23 10 dargeboten?","a":"S23 10 ist ein orales androgen-anaboles Steroid (SARM) und enthält S23 10mg/tab. Es liegt in Form von Compresse (uso orale) mit einer Konzentration oder Einzeldosierung von 10 mg/tab vor, in einer Packung zu 50 compresse — uso orale. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"Aromatisiert es?","a":"Die Neigung zur Aromatisierung ist eine chemische Eigenschaft des Moleküls: Unter den oralen Präparaten aromatisiert beispielsweise Methandienon, während Oxandrolon und Stanozolol nicht aromatisieren. Der spezifische Wirkstoff ist in S23 10mg/tab angegeben."},{"q":"Was bedeutet 17-alpha-alkyliert?","a":"Viele orale Steroide sind 17-alpha-alkyliert, eine chemische Modifikation, die die orale Aufnahme ermöglicht, indem sie dem hepatischen First-Pass-Metabolismus widersteht. Es ist ein strukturelles Merkmal des Moleküls, kein Anwendungshinweis."},{"q":"Wie wird es gelagert?","a":"An einem kühlen, trockenen Ort, geschützt vor Licht und Feuchtigkeit lagern, gemäß den Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Comment se présente S23 10 ?","a":"S23 10 est un stéroïde androgénique-anabolisant oral (SARM) et contient S23 10mg/tab. Il se présente sous forme de Compresse (uso orale) avec une concentration ou un dosage unitaire de 10 mg/tab, en conditionnement de 50 compresse — uso orale. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Aromatise-t-il ?","a":"La tendance à aromatiser est une propriété chimique de la molécule : parmi les oraux, par exemple, la méthandiénone aromatise, tandis que l''oxandrolone et le stanozolol n''aromatisent pas. Le principe actif spécifique est indiqué dans S23 10mg/tab."},{"q":"Que signifie 17-alpha-alkylé ?","a":"De nombreux stéroïdes oraux sont 17-alpha-alkylés, une modification chimique qui permet leur passage par voie orale en résistant au métabolisme hépatique de premier passage. Il s''agit d''une caractéristique structurelle de la molécule, non d''un conseil d''utilisation."},{"q":"Comment se conserve-t-il ?","a":"Conserver dans un endroit frais et sec, à l''abri de la lumière et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"Como se apresenta S23 10?","a":"S23 10 é um esteroide androgénico-anabolizante oral (SARM) e contém S23 10mg/tab. Apresenta-se sob a forma de Compresse (uso orale) com uma concentração ou dosagem unitária de 10 mg/tab, em embalagem de 50 compresse — uso orale. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Aromatiza?","a":"A tendência para aromatizar é uma propriedade química da molécula: entre os orais, por exemplo, a metandienona aromatiza, enquanto a oxandrolona e o stanozolol não aromatizam. O princípio ativo específico está indicado em S23 10mg/tab."},{"q":"O que significa ser 17-alfa-alquilado?","a":"Muitos esteroides orais são 17-alfa-alquilados, uma modificação química que permite a sua passagem por via oral, resistindo ao metabolismo hepático de primeira passagem. É uma característica estrutural da molécula, não um conselho de utilização."},{"q":"Como se conserva?","a":"Conservar em local fresco e seco, ao abrigo da luz e da humidade, de acordo com as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='s23-10';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è un SARM?","a":"S4 25 appartiene alla classe dei modulatori selettivi del recettore androgeno (SARM), a cui appartengono ostarine, ligandrol e RAD-140. Queste molecole interagiscono in modo selettivo con il recettore androgeno. Il principio attivo è Andarine (S4) 25mg/tab, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Un SARM è uno steroide?","a":"No. I SARM agiscono sullo stesso recettore androgeno ma hanno struttura non steroidea e un profilo di selettività differente rispetto agli steroidi androgeno-anabolizzanti. Sono classi distinte."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Compresse (uso orale) con concentrazione 25 mg/tab, in confezione da 50 compresse — uso orale."},{"q":"Fornite indicazioni su come assumerlo?","a":"Le informazioni disponibili riguardano composizione, classe e meccanismo e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a SARM?","a":"S4 25 belongs to the class of selective androgen receptor modulators (SARM), to which ostarine, ligandrol and RAD-140 belong. These molecules interact selectively with the androgen receptor. The active ingredient is Andarine (S4) 25mg/tab, supplied exclusively for research and analytical evaluation purposes only."},{"q":"Is a SARM a steroid?","a":"No. SARMs act on the same androgen receptor but have a non-steroidal structure and a different selectivity profile compared to androgenic-anabolic steroids. They are distinct classes."},{"q":"In what form is it available?","a":"It is available in the form of Compresse (uso orale) with a concentration of 25 mg/tab, in a pack of 50 compresse — uso orale."},{"q":"Do you provide instructions on how to take it?","a":"The in