update public.products set faqs_i18n='{"it":[{"q":"Cosa contiene questo peptide?","a":"BPC 157 contiene BPC-157 Pentadecapeptide 5mg/vial e appartiene alla classe dei peptidi di sintesi (Peptide), categoria che comprende molecole come BPC-157, TB-500, ipamorelin e melanotan. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino liofilizzato con titolo 5 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"I peptidi hanno tutti lo stesso meccanismo?","a":"No. Sotto la definizione di peptidi di sintesi rientrano molecole con bersagli molto diversi tra loro. Il meccanismo dipende dal peptide specifico indicato in BPC-157 Pentadecapeptide 5mg/vial."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in luogo fresco o refrigerato; una volta ricostituito richiede in genere refrigerazione. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What does this peptide contain?","a":"BPC 157 contains BPC-157 Pentadecapeptide 5mg/vial and belongs to the class of synthetic peptides (Peptide), a category that includes molecules such as BPC-157, TB-500, ipamorelin and melanotan. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it supplied?","a":"It is typically supplied as lyophilized Flaconcino with a titer of 5 mg, in a pack of 1 flaconcino. The lyophilized form requires reconstitution before analysis."},{"q":"Do all peptides have the same mechanism?","a":"No. The definition of synthetic peptides covers molecules with very different targets from one another. The mechanism depends on the specific peptide indicated in BPC-157 Pentadecapeptide 5mg/vial."},{"q":"How is it stored?","a":"The lyophilized product is stored in a cool or refrigerated place; once reconstituted it generally requires refrigeration. Refer to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was enthält dieses Peptid?","a":"BPC 157 enthält BPC-157 Pentadecapeptide 5mg/vial und gehört zur Klasse der synthetischen Peptide (Peptide), einer Kategorie, die Moleküle wie BPC-157, TB-500, Ipamorelin und Melanotan umfasst. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form wird es geliefert?","a":"Es wird typischerweise als lyophilisiertes Flaconcino mit einem Gehalt von 5 mg geliefert, in einer Packung zu 1 flaconcino. Die lyophilisierte Form erfordert eine Rekonstitution vor der Analyse."},{"q":"Haben alle Peptide denselben Mechanismus?","a":"Nein. Unter die Definition der synthetischen Peptide fallen Moleküle mit sehr unterschiedlichen Zielstrukturen. Der Mechanismus hängt von dem in BPC-157 Pentadecapeptide 5mg/vial angegebenen spezifischen Peptid ab."},{"q":"Wie wird es gelagert?","a":"Das lyophilisierte Produkt wird an einem kühlen oder gekühlten Ort gelagert; nach der Rekonstitution ist in der Regel eine Kühlung erforderlich. Beachten Sie die Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Que contient ce peptide ?","a":"BPC 157 contient BPC-157 Pentadecapeptide 5mg/vial et appartient à la classe des peptides de synthèse (Peptide), une catégorie qui comprend des molécules comme le BPC-157, le TB-500, l''ipamoréline et le mélanotan. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il fourni ?","a":"Il est généralement fourni sous forme de Flaconcino lyophilisé avec un titre de 5 mg, en conditionnement de 1 flaconcino. La forme lyophilisée nécessite une reconstitution avant l''analyse."},{"q":"Tous les peptides ont-ils le même mécanisme ?","a":"Non. La définition de peptides de synthèse regroupe des molécules aux cibles très différentes les unes des autres. Le mécanisme dépend du peptide spécifique indiqué dans BPC-157 Pentadecapeptide 5mg/vial."},{"q":"Comment se conserve-t-il ?","a":"Le produit lyophilisé se conserve dans un endroit frais ou réfrigéré ; une fois reconstitué, il nécessite généralement une réfrigération. Se référer aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que contém este péptido?","a":"BPC 157 contém BPC-157 Pentadecapeptide 5mg/vial e pertence à classe dos péptidos de síntese (Peptide), uma categoria que inclui moléculas como o BPC-157, o TB-500, a ipamorelina e o melanotan. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma é fornecido?","a":"É normalmente fornecido como Flaconcino liofilizado com um título de 5 mg, em embalagem de 1 flaconcino. A forma liofilizada requer reconstituição antes da análise."},{"q":"Todos os péptidos têm o mesmo mecanismo?","a":"Não. Sob a definição de péptidos de síntese enquadram-se moléculas com alvos muito diferentes entre si. O mecanismo depende do péptido específico indicado em BPC-157 Pentadecapeptide 5mg/vial."},{"q":"Como se conserva?","a":"O produto liofilizado conserva-se em local fresco ou refrigerado; uma vez reconstituído, requer geralmente refrigeração. Consultar as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='bpc-157';
