update public.products set faqs_i18n='{"it":[{"q":"Cos''è l''hCG?","a":"HCG contiene Human Chorionic Gonadotropin 5000IU/vial, ovvero gonadotropina corionica umana, un ormone glicoproteico che nella classe Gonadotropina corionica (hCG) agisce sui recettori dell''ormone luteinizzante. Il prodotto è fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino, con concentrazione 5000 iu e confezione 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"Come si conserva l''hCG?","a":"Il prodotto liofilizzato si conserva generalmente in luogo fresco; una volta ricostituito richiede refrigerazione. Fare sempre riferimento alle indicazioni sulla confezione."},{"q":"Fornite indicazioni su come utilizzarlo?","a":"Le informazioni disponibili sono di natura fattuale sulla composizione e sulla classe farmacologica e non costituiscono un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is hCG?","a":"HCG contains Human Chorionic Gonadotropin 5000IU/vial, i.e. human chorionic gonadotropin, a glycoprotein hormone that, within the Gonadotropina corionica (hCG) class, acts on luteinizing hormone receptors. The product is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it supplied?","a":"It is typically supplied as Flaconcino, with a concentration of 5000 iu and 1 flaconcino packaging. The lyophilized form requires reconstitution before analysis."},{"q":"How is hCG stored?","a":"The lyophilized product is generally stored in a cool place; once reconstituted it requires refrigeration. Always refer to the instructions on the packaging."},{"q":"Do you provide instructions on how to use it?","a":"The information available is factual in nature, concerning composition and pharmacological class, and does not constitute a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist hCG?","a":"HCG enthält Human Chorionic Gonadotropin 5000IU/vial, also humanes Choriongonadotropin, ein Glykoproteinhormon, das in der Klasse Gonadotropina corionica (hCG) auf die Rezeptoren des luteinisierenden Hormons wirkt. Das Produkt wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form wird es geliefert?","a":"Es wird typischerweise als Flaconcino geliefert, mit einer Konzentration von 5000 iu und einer Verpackung von 1 flaconcino. Die lyophilisierte Form erfordert eine Rekonstitution vor der Analyse."},{"q":"Wie wird hCG gelagert?","a":"Das lyophilisierte Produkt wird in der Regel an einem kühlen Ort gelagert; nach der Rekonstitution ist eine Kühlung erforderlich. Beachten Sie stets die Angaben auf der Verpackung."},{"q":"Geben Sie Hinweise zur Anwendung?","a":"Die verfügbaren Informationen sind sachlicher Natur und betreffen die Zusammensetzung und die pharmakologische Klasse; sie stellen kein Protokoll und keine medizinische Beratung dar. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce que l''hCG ?","a":"HCG contient Human Chorionic Gonadotropin 5000IU/vial, c''est-à-dire la gonadotrophine chorionique humaine, une hormone glycoprotéique qui, dans la classe Gonadotropina corionica (hCG), agit sur les récepteurs de l''hormone lutéinisante. Le produit est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il fourni ?","a":"Il est généralement fourni sous forme de Flaconcino, avec une concentration de 5000 iu et un conditionnement 1 flaconcino. La forme lyophilisée nécessite une reconstitution avant l''analyse."},{"q":"Comment se conserve l''hCG ?","a":"Le produit lyophilisé se conserve généralement dans un endroit frais ; une fois reconstitué, il nécessite une réfrigération. Se référer toujours aux indications figurant sur l''emballage."},{"q":"Fournissez-vous des indications sur son utilisation ?","a":"Les informations disponibles sont de nature factuelle et concernent la composition et la classe pharmacologique ; elles ne constituent pas un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é a hCG?","a":"HCG contém Human Chorionic Gonadotropin 5000IU/vial, ou seja, gonadotrofina coriónica humana, uma hormona glicoproteica que, na classe Gonadotropina corionica (hCG), atua sobre os recetores da hormona luteinizante. O produto é fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma é fornecido?","a":"É normalmente fornecido como Flaconcino, com uma concentração de 5000 iu e embalagem 1 flaconcino. A forma liofilizada requer reconstituição antes da análise."},{"q":"Como se conserva a hCG?","a":"O produto liofilizado conserva-se geralmente em local fresco; uma vez reconstituído, requer refrigeração. Consultar sempre as indicações na embalagem."},{"q":"Fornecem indicações sobre como utilizá-lo?","a":"As informações disponíveis são de natureza factual, relativas à composição e à classe farmacológica, e não constituem um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='hcg';
update public.products set faqs_i18n='{"it":[{"q":"Cosa contiene HEXARELIN?","a":"HEXARELIN contiene Hexarelin 2mg/vial e appartiene alla classe HGH / Peptide. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Flaconcino con concentrazione 2 mg, in confezione da 1 flaconcino."},{"q":"Fornite indicazioni su come utilizzarlo?","a":"Le informazioni disponibili riguardano composizione, classe farmacologica e caratteristiche del prodotto e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Come si conserva?","a":"Si consiglia di conservare il prodotto in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità, secondo le indicazioni riportate sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What does HEXARELIN contain?","a":"HEXARELIN contains Hexarelin 2mg/vial and belongs to the HGH / Peptide class. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it available?","a":"It is available in the form of Flaconcino with a concentration of 2 mg, in a pack of 1 flaconcino."},{"q":"Do you provide instructions on how to use it?","a":"The information available concerns composition, pharmacological class and product characteristics and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"How is it stored?","a":"It is recommended to store the product in a cool, dry place, protected from direct light and humidity, according to the instructions printed on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was enthält HEXARELIN?","a":"HEXARELIN enthält Hexarelin 2mg/vial und gehört zur Klasse HGH / Peptide. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Flaconcino mit einer Konzentration von 2 mg erhältlich, in einer Packung zu 1 flaconcino."},{"q":"Geben Sie Hinweise zur Anwendung?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, pharmakologische Klasse und Produkteigenschaften und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Wie wird es gelagert?","a":"Es wird empfohlen, das Produkt an einem kühlen, trockenen Ort, geschützt vor direktem Licht und Feuchtigkeit, gemäß den Angaben auf der Verpackung zu lagern."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Que contient HEXARELIN ?","a":"HEXARELIN contient Hexarelin 2mg/vial et appartient à la classe HGH / Peptide. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Flaconcino avec une concentration de 2 mg, en conditionnement de 1 flaconcino."},{"q":"Fournissez-vous des indications sur son utilisation ?","a":"Les informations disponibles concernent la composition, la classe pharmacologique et les caractéristiques du produit et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Comment se conserve-t-il ?","a":"Il est conseillé de conserver le produit dans un endroit frais et sec, à l''abri de la lumière directe et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que contém HEXARELIN?","a":"HEXARELIN contém Hexarelin 2mg/vial e pertence à classe HGH / Peptide. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Flaconcino com uma concentração de 2 mg, em embalagem de 1 flaconcino."},{"q":"Fornecem indicações sobre como utilizá-lo?","a":"As informações disponíveis dizem respeito à composição, classe farmacológica e características do produto e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"Como se conserva?","a":"Recomenda-se conservar o produto em local fresco e seco, ao abrigo da luz direta e da humidade, de acordo com as indicações apresentadas na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='hexarelin';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è l''ormone della crescita?","a":"HGH FRAGMENT 176-191 contiene hGH Fragment 176-191 5mg/vial, ovvero somatropina, la forma ricombinante dell''ormone della crescita umano; appartiene alla classe Ormone della crescita (somatropina). È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito generalmente come Flaconcino liofilizzato con titolo 5 mg, in confezione da 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"Come si misura la somatropina?","a":"Il contenuto di somatropina viene espresso in unità internazionali (UI) o in milligrammi. Il titolo specifico di questo prodotto è riportato in 5 mg."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in genere refrigerato; una volta ricostituito va mantenuto in frigorifero. Fare sempre riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is growth hormone?","a":"HGH FRAGMENT 176-191 contains hGH Fragment 176-191 5mg/vial, i.e. somatropin, the recombinant form of human growth hormone; it belongs to the Ormone della crescita (somatropina) class. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it supplied?","a":"It is generally supplied as lyophilized Flaconcino with a titer of 5 mg, in a pack of 1 flaconcino. The lyophilized form requires reconstitution before analysis."},{"q":"How is somatropin measured?","a":"The somatropin content is expressed in international units (IU) or in milligrams. The specific titer of this product is stated in 5 mg."},{"q":"How is it stored?","a":"The lyophilized product is generally stored refrigerated; once reconstituted it must be kept refrigerated. Always refer to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist Wachstumshormon?","a":"HGH FRAGMENT 176-191 enthält hGH Fragment 176-191 5mg/vial, also Somatropin, die rekombinante Form des menschlichen Wachstumshormons; es gehört zur Klasse Ormone della crescita (somatropina). Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form wird es geliefert?","a":"Es wird in der Regel als lyophilisiertes Flaconcino mit einem Gehalt von 5 mg geliefert, in einer Packung zu 1 flaconcino. Die lyophilisierte Form erfordert eine Rekonstitution vor der Analyse."},{"q":"Wie wird Somatropin gemessen?","a":"Der Somatropingehalt wird in internationalen Einheiten (IE) oder in Milligramm ausgedrückt. Der spezifische Gehalt dieses Produkts ist in 5 mg angegeben."},{"q":"Wie wird es gelagert?","a":"Das lyophilisierte Produkt wird in der Regel gekühlt gelagert; nach der Rekonstitution ist es im Kühlschrank aufzubewahren. Beachten Sie stets die Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce que l''hormone de croissance ?","a":"HGH FRAGMENT 176-191 contient hGH Fragment 176-191 5mg/vial, c''est-à-dire la somatropine, la forme recombinante de l''hormone de croissance humaine ; il appartient à la classe Ormone della crescita (somatropina). Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il fourni ?","a":"Il est généralement fourni sous forme de Flaconcino lyophilisé avec un titre de 5 mg, en conditionnement de 1 flaconcino. La forme lyophilisée nécessite une reconstitution avant l''analyse."},{"q":"Comment mesure-t-on la somatropine ?","a":"La teneur en somatropine est exprimée en unités internationales (UI) ou en milligrammes. Le titre spécifique de ce produit est indiqué dans 5 mg."},{"q":"Comment se conserve-t-il ?","a":"Le produit lyophilisé se conserve généralement au réfrigérateur ; une fois reconstitué, il doit être maintenu au réfrigérateur. Se référer toujours aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é a hormona do crescimento?","a":"HGH FRAGMENT 176-191 contém hGH Fragment 176-191 5mg/vial, ou seja, somatropina, a forma recombinante da hormona do crescimento humana; pertence à classe Ormone della crescita (somatropina). É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma é fornecido?","a":"É geralmente fornecido como Flaconcino liofilizado com um título de 5 mg, em embalagem de 1 flaconcino. A forma liofilizada requer reconstituição antes da análise."},{"q":"Como se mede a somatropina?","a":"O teor de somatropina é expresso em unidades internacionais (UI) ou em miligramas. O título específico deste produto está indicado em 5 mg."},{"q":"Como se conserva?","a":"O produto liofilizado conserva-se geralmente refrigerado; uma vez reconstituído, deve ser mantido no frigorífico. Consultar sempre as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='hgh-fragment-176-191';
update public.products set faqs_i18n='{"it":[{"q":"Cos''è l''hCG?","a":"HMG contiene Human Menopausal Gonadotropin 0.15mg/vial, ovvero gonadotropina corionica umana, un ormone glicoproteico che nella classe Gonadotropina corionica (hCG) agisce sui recettori dell''ormone luteinizzante. Il prodotto è fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino, con concentrazione 0.15 mg e confezione 1 flaconcino. La forma liofilizzata richiede ricostituzione prima dell''analisi."},{"q":"Come si conserva l''hCG?","a":"Il prodotto liofilizzato si conserva generalmente in luogo fresco; una volta ricostituito richiede refrigerazione. Fare sempre riferimento alle indicazioni sulla confezione."},{"q":"Fornite indicazioni su come utilizzarlo?","a":"Le informazioni disponibili sono di natura fattuale sulla composizione e sulla classe farmacologica e non costituiscono un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is hCG?","a":"HMG contains Human Menopausal Gonadotropin 0.15mg/vial, i.e. human chorionic gonadotropin, a glycoprotein hormone that, within the Gonadotropina corionica (hCG) class, acts on luteinizing hormone receptors. The product is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it supplied?","a":"It is typically supplied as Flaconcino, with a concentration of 0.15 mg and 1 flaconcino packaging. The lyophilized form requires reconstitution before analysis."},{"q":"How is hCG stored?","a":"The lyophilized product is generally stored in a cool place; once reconstituted it requires refrigeration. Always refer to the instructions on the packaging."},{"q":"Do you provide instructions on how to use it?","a":"The information available is factual in nature, concerning composition and pharmacological class, and does not constitute a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist hCG?","a":"HMG enthält Human Menopausal Gonadotropin 0.15mg/vial, also humanes Choriongonadotropin, ein Glykoproteinhormon, das in der Klasse Gonadotropina corionica (hCG) auf die Rezeptoren des luteinisierenden Hormons wirkt. Das Produkt wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form wird es geliefert?","a":"Es wird typischerweise als Flaconcino geliefert, mit einer Konzentration von 0.15 mg und einer Verpackung von 1 flaconcino. Die lyophilisierte Form erfordert eine Rekonstitution vor der Analyse."},{"q":"Wie wird hCG gelagert?","a":"Das lyophilisierte Produkt wird in der Regel an einem kühlen Ort gelagert; nach der Rekonstitution ist eine Kühlung erforderlich. Beachten Sie stets die Angaben auf der Verpackung."},{"q":"Geben Sie Hinweise zur Anwendung?","a":"Die verfügbaren Informationen sind sachlicher Natur und betreffen die Zusammensetzung und die pharmakologische Klasse; sie stellen kein Protokoll und keine medizinische Beratung dar. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce que l''hCG ?","a":"HMG contient Human Menopausal Gonadotropin 0.15mg/vial, c''est-à-dire la gonadotrophine chorionique humaine, une hormone glycoprotéique qui, dans la classe Gonadotropina corionica (hCG), agit sur les récepteurs de l''hormone lutéinisante. Le produit est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il fourni ?","a":"Il est généralement fourni sous forme de Flaconcino, avec une concentration de 0.15 mg et un conditionnement 1 flaconcino. La forme lyophilisée nécessite une reconstitution avant l''analyse."},{"q":"Comment se conserve l''hCG ?","a":"Le produit lyophilisé se conserve généralement dans un endroit frais ; une fois reconstitué, il nécessite une réfrigération. Se référer toujours aux indications figurant sur l''emballage."},{"q":"Fournissez-vous des indications sur son utilisation ?","a":"Les informations disponibles sont de nature factuelle et concernent la composition et la classe pharmacologique ; elles ne constituent pas un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é a hCG?","a":"HMG contém Human Menopausal Gonadotropin 0.15mg/vial, ou seja, gonadotrofina coriónica humana, uma hormona glicoproteica que, na classe Gonadotropina corionica (hCG), atua sobre os recetores da hormona luteinizante. O produto é fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma é fornecido?","a":"É normalmente fornecido como Flaconcino, com uma concentração de 0.15 mg e embalagem 1 flaconcino. A forma liofilizada requer reconstituição antes da análise."},{"q":"Como se conserva a hCG?","a":"O produto liofilizado conserva-se geralmente em local fresco; uma vez reconstituído, requer refrigeração. Consultar sempre as indicações na embalagem."},{"q":"Fornecem indicações sobre como utilizá-lo?","a":"As informações disponíveis são de natureza factual, relativas à composição e à classe farmacológica, e não constituem um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='hmg';
