update public.products set faqs_i18n='{"it":[{"q":"Cos''è un agonista GLP-1?","a":"TIRZEPATIDE appartiene alla classe degli agonisti del recettore GLP-1 (Agonista GLP-1), a cui appartengono molecole come semaglutide e tirzepatide. Questi peptidi mimano l''azione dell''ormone GLP-1 sui suoi recettori. Il principio attivo è Tirzepatide (GIP/GLP-1) 10mg/vial, fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma viene fornito?","a":"Viene fornito tipicamente come Flaconcino con concentrazione 10 mg; la forma liofilizzata richiede ricostituzione prima dell''analisi. La confezione è 1 flaconcino."},{"q":"Semaglutide e tirzepatide sono la stessa cosa?","a":"No. La semaglutide è un agonista del solo recettore GLP-1, mentre la tirzepatide è un doppio agonista GLP-1/GIP. Il principio attivo specifico è indicato in Tirzepatide (GIP/GLP-1) 10mg/vial."},{"q":"Come si conserva?","a":"Il prodotto liofilizzato si conserva in luogo fresco; una volta ricostituito richiede in genere refrigerazione. Fare riferimento alle indicazioni sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What is a GLP-1 agonist?","a":"TIRZEPATIDE belongs to the class of GLP-1 receptor agonists (Agonista GLP-1), to which molecules such as semaglutide and tirzepatide belong. These peptides mimic the action of the GLP-1 hormone on its receptors. The active ingredient is Tirzepatide (GIP/GLP-1) 10mg/vial, supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it supplied?","a":"It is typically supplied as Flaconcino with a concentration of 10 mg; the lyophilized form requires reconstitution before analysis. The packaging is 1 flaconcino."},{"q":"Are semaglutide and tirzepatide the same thing?","a":"No. Semaglutide is an agonist of the GLP-1 receptor alone, whereas tirzepatide is a dual GLP-1/GIP agonist. The specific active ingredient is indicated in Tirzepatide (GIP/GLP-1) 10mg/vial."},{"q":"How is it stored?","a":"The lyophilized product is stored in a cool place; once reconstituted it generally requires refrigeration. Refer to the instructions on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was ist ein GLP-1-Agonist?","a":"TIRZEPATIDE gehört zur Klasse der GLP-1-Rezeptoragonisten (Agonista GLP-1), zu der Moleküle wie Semaglutid und Tirzepatid gehören. Diese Peptide ahmen die Wirkung des Hormons GLP-1 an seinen Rezeptoren nach. Der Wirkstoff ist Tirzepatide (GIP/GLP-1) 10mg/vial und wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form wird es geliefert?","a":"Es wird typischerweise als Flaconcino mit einer Konzentration von 10 mg geliefert; die lyophilisierte Form erfordert eine Rekonstitution vor der Analyse. Die Verpackung ist 1 flaconcino."},{"q":"Sind Semaglutid und Tirzepatid dasselbe?","a":"Nein. Semaglutid ist ein Agonist allein des GLP-1-Rezeptors, während Tirzepatid ein dualer GLP-1/GIP-Agonist ist. Der spezifische Wirkstoff ist in Tirzepatide (GIP/GLP-1) 10mg/vial angegeben."},{"q":"Wie wird es gelagert?","a":"Das lyophilisierte Produkt wird an einem kühlen Ort gelagert; nach der Rekonstitution ist in der Regel eine Kühlung erforderlich. Beachten Sie die Angaben auf der Verpackung."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Qu''est-ce qu''un agoniste du GLP-1 ?","a":"TIRZEPATIDE appartient à la classe des agonistes du récepteur GLP-1 (Agonista GLP-1), à laquelle appartiennent des molécules comme le sémaglutide et le tirzépatide. Ces peptides miment l''action de l''hormone GLP-1 sur ses récepteurs. Le principe actif est Tirzepatide (GIP/GLP-1) 10mg/vial, fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il fourni ?","a":"Il est généralement fourni sous forme de Flaconcino avec une concentration de 10 mg ; la forme lyophilisée nécessite une reconstitution avant l''analyse. Le conditionnement est 1 flaconcino."},{"q":"Le sémaglutide et le tirzépatide sont-ils la même chose ?","a":"Non. Le sémaglutide est un agoniste du seul récepteur GLP-1, tandis que le tirzépatide est un double agoniste GLP-1/GIP. Le principe actif spécifique est indiqué dans Tirzepatide (GIP/GLP-1) 10mg/vial."},{"q":"Comment se conserve-t-il ?","a":"Le produit lyophilisé se conserve dans un endroit frais ; une fois reconstitué, il nécessite généralement une réfrigération. Se référer aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que é um agonista do GLP-1?","a":"TIRZEPATIDE pertence à classe dos agonistas do recetor GLP-1 (Agonista GLP-1), à qual pertencem moléculas como a semaglutida e a tirzepatida. Estes péptidos mimetizam a ação da hormona GLP-1 nos seus recetores. O princípio ativo é Tirzepatide (GIP/GLP-1) 10mg/vial, fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma é fornecido?","a":"É normalmente fornecido como Flaconcino com uma concentração de 10 mg; a forma liofilizada requer reconstituição antes da análise. A embalagem é 1 flaconcino."},{"q":"A semaglutida e a tirzepatida são a mesma coisa?","a":"Não. A semaglutida é um agonista apenas do recetor GLP-1, enquanto a tirzepatida é um duplo agonista GLP-1/GIP. O princípio ativo específico está indicado em Tirzepatide (GIP/GLP-1) 10mg/vial."},{"q":"Como se conserva?","a":"O produto liofilizado conserva-se em local fresco; uma vez reconstituído, requer geralmente refrigeração. Consultar as indicações na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='tirzepatide';
update public.products set faqs_i18n='{"it":[{"q":"Cosa contiene THYMALIN?","a":"THYMALIN contiene Thymalin Thymic factor 10mg/vial e appartiene alla classe HGH / Peptide. È fornito esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"In che forma è disponibile?","a":"È disponibile in forma di Flaconcino con concentrazione 10 mg, in confezione da 1 flaconcino."},{"q":"Fornite indicazioni su come utilizzarlo?","a":"Le informazioni disponibili riguardano composizione, classe farmacologica e caratteristiche del prodotto e sono di natura fattuale, non un protocollo o un consiglio medico. Il prodotto è destinato esclusivamente a scopo di ricerca e valutazione analitica."},{"q":"Come si conserva?","a":"Si consiglia di conservare il prodotto in luogo fresco e asciutto, al riparo dalla luce diretta e dall''umidità, secondo le indicazioni riportate sulla confezione."},{"q":"La qualità è verificata?","a":"Sì. Ogni lotto è verificabile nella sezione Lab test / QC della scheda prodotto."}],"en":[{"q":"What does THYMALIN contain?","a":"THYMALIN contains Thymalin Thymic factor 10mg/vial and belongs to the HGH / Peptide class. It is supplied exclusively for research and analytical evaluation purposes only."},{"q":"In what form is it available?","a":"It is available in the form of Flaconcino with a concentration of 10 mg, in a pack of 1 flaconcino."},{"q":"Do you provide instructions on how to use it?","a":"The information available concerns composition, pharmacological class and product characteristics and is factual in nature, not a protocol or medical advice. The product is intended exclusively for research and analytical evaluation purposes only."},{"q":"How is it stored?","a":"It is recommended to store the product in a cool, dry place, protected from direct light and humidity, according to the instructions printed on the packaging."},{"q":"Is the quality verified?","a":"Yes. Every batch can be verified in the Lab test / QC section of the product page."}],"de":[{"q":"Was enthält THYMALIN?","a":"THYMALIN enthält Thymalin Thymic factor 10mg/vial und gehört zur Klasse HGH / Peptide. Es wird ausschließlich zu Forschungs- und analytischen Bewertungszwecken bereitgestellt."},{"q":"In welcher Form ist es erhältlich?","a":"Es ist in Form von Flaconcino mit einer Konzentration von 10 mg erhältlich, in einer Packung zu 1 flaconcino."},{"q":"Geben Sie Hinweise zur Anwendung?","a":"Die verfügbaren Informationen betreffen Zusammensetzung, pharmakologische Klasse und Produkteigenschaften und sind sachlicher Natur, kein Protokoll und keine medizinische Beratung. Das Produkt ist ausschließlich für Forschungs- und analytische Bewertungszwecke bestimmt."},{"q":"Wie wird es gelagert?","a":"Es wird empfohlen, das Produkt an einem kühlen, trockenen Ort, geschützt vor direktem Licht und Feuchtigkeit, gemäß den Angaben auf der Verpackung zu lagern."},{"q":"Ist die Qualität geprüft?","a":"Ja. Jede Charge ist im Bereich Lab test / QC der Produktseite überprüfbar."}],"fr":[{"q":"Que contient THYMALIN ?","a":"THYMALIN contient Thymalin Thymic factor 10mg/vial et appartient à la classe HGH / Peptide. Il est fourni exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Sous quelle forme est-il disponible ?","a":"Il est disponible sous forme de Flaconcino avec une concentration de 10 mg, en conditionnement de 1 flaconcino."},{"q":"Fournissez-vous des indications sur son utilisation ?","a":"Les informations disponibles concernent la composition, la classe pharmacologique et les caractéristiques du produit et sont de nature factuelle, non un protocole ni un conseil médical. Le produit est destiné exclusivement à des fins de recherche et d''évaluation analytique."},{"q":"Comment se conserve-t-il ?","a":"Il est conseillé de conserver le produit dans un endroit frais et sec, à l''abri de la lumière directe et de l''humidité, conformément aux indications figurant sur l''emballage."},{"q":"La qualité est-elle vérifiée ?","a":"Oui. Chaque lot est vérifiable dans la section Lab test / QC de la fiche produit."}],"pt":[{"q":"O que contém THYMALIN?","a":"THYMALIN contém Thymalin Thymic factor 10mg/vial e pertence à classe HGH / Peptide. É fornecido exclusivamente para fins de investigação e avaliação analítica."},{"q":"Em que forma está disponível?","a":"Está disponível sob a forma de Flaconcino com uma concentração de 10 mg, em embalagem de 1 flaconcino."},{"q":"Fornecem indicações sobre como utilizá-lo?","a":"As informações disponíveis dizem respeito à composição, classe farmacológica e características do produto e são de natureza factual, não um protocolo nem um conselho médico. O produto destina-se exclusivamente a fins de investigação e avaliação analítica."},{"q":"Como se conserva?","a":"Recomenda-se conservar o produto em local fresco e seco, ao abrigo da luz direta e da humidade, de acordo com as indicações apresentadas na embalagem."},{"q":"A qualidade é verificada?","a":"Sim. Cada lote pode ser verificado na secção Lab test / QC da ficha do produto."}]}'::jsonb, updated_at=now() where slug='thymalin';
